// ../app/dist/cli/services/dev/select-app.js
async function selectOrCreateApp(apps, hasMorePages, org, developerPlatformClient, options) {
  let createNewApp = apps.length === 0;
  if (createNewApp || (createNewApp = await createAsNewAppPrompt()), createNewApp) {
    let name = await appNamePrompt(options.name);
    return developerPlatformClient.createApp(org, { ...options, name });
  } else {
    let app = await selectAppPrompt(searchForAppsByNameFactory(developerPlatformClient, org.id), apps, hasMorePages, {
      directory: options.directory
    }), selectedToml = (getCachedCommandInfo()?.tomls ?? {})[app.apiKey];
    selectedToml && setCachedCommandTomlPreference(selectedToml);
    let fullSelectedApp = await developerPlatformClient.appFromIdentifiers(app);
    if (!fullSelectedApp)
      throw new BugError(`Unable to fetch app ${app.apiKey} from Shopify`, "Try running `shopify app config link` to connect to an app you have access to.");
    return fullSelectedApp;
  }
}

